using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using MotorwaysSim;
class Diagnostic {
static object Pose(Point p)=>new[]{p.X,p.Y};
static Point Ahead(Vehicle c,double delta,out Point h){int i=c.RouteIndex;delta+=c.DistanceAlongLane;while(i<c.Lanes.Count-1&&delta>c.Lanes[i].Length){delta-=c.Lanes[i].Length;i++;}h=c.Lanes[i].Tangent(Math.Min(delta,c.Lanes[i].Length));return c.Lanes[i].Position(Math.Min(delta,c.Lanes[i].Length));}
static void Main(string[] args){TrafficWorld w;
if(args.Length>0&&args[0]=="eight"){var rules=Rules.ForVersion(GameVersion.OriginalReference);rules.EnableCityGrowth=false;rules.OvercrowdingSeconds=100000;w=new TrafficWorld(40,false,rules);w.Reset(40,ScenarioKind.EmptyLab);w.Inventory[0]=1000;var shop=w.SpawnBuilding(new Cell(20,10),0,false);foreach(var cell in new[]{new Cell(5,12),new Cell(5,15),new Cell(5,18),new Cell(5,21)}){var home=w.SpawnBuilding(cell,0,true);w.DrawRoad(home.Access,new Cell(10,cell.Y));w.DrawRoad(new Cell(10,cell.Y),new Cell(10,12));}w.DrawRoad(new Cell(10,12),shop.Access);shop.Demand=8;shop.DemandCountdown=1e9;w.Step(6000);}
else if(args.Length>0){var d=JsonSerializer.Deserialize<CustomScenarioDefinition>(System.IO.File.ReadAllText(args[0]),new JsonSerializerOptions{IncludeFields=true,PropertyNameCaseInsensitive=true});var s=new CustomScenarioSession(d);while(!s.Complete)s.AdvanceTick();w=s.World;}
else{var rules=Rules.ForVersion(GameVersion.OriginalReference);rules.EnableCityGrowth=false;rules.OvercrowdingSeconds=100000;w=new TrafficWorld(42,false,rules);w.Reset(42,ScenarioKind.EmptyLab);var center=new Cell(15,15);foreach(var cell in new[]{new Cell(10,15),new Cell(20,15),new Cell(15,10)}){var home=w.SpawnBuilding(cell,0,true);w.DrawRoad(home.Access,center);}var shop=w.SpawnBuilding(new Cell(14,20),0,false,0,2);w.DrawRoad(center,new Cell(15,19));w.DrawRoad(new Cell(15,19),new Cell(14,19));w.DrawRoad(new Cell(14,19),shop.Access);shop.Demand=6;shop.DemandCountdown=1e9;shop.NextDemand=1e9;w.Step(100);w.Inventory[4]=1;w.Build(BuildTool.Roundabout,center);w.Step(7900);}
Console.WriteLine(JsonSerializer.Serialize(new{w.Time,w.TripsCompleted,w.Failed,reservations=((Dictionary<(int,Cell),int>)typeof(TrafficWorld).GetField("carparkThroats",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(w)).Select(e=>new{key=e.Key.ToString(),owner=e.Value}),cars=w.Cars.Select(c=>new{c.Id,c.ShopId,c.Stage,c.ParkingSlot,c.RouteIndex,c.DistanceAlongLane,c.Waiting,c.Obstacle,pos=Pose(c.Position),heading=Pose(c.Heading),lanes=c.Lanes.Skip(c.RouteIndex).Select(l=>new{l.Key,l.Length,samples=l.Samples.Select(Pose)}),blockedBy=!c.Moving?new int[0]:w.Cars.Where(o=>o.Id!=c.Id&&o.ShopId==c.ShopId&&o.Stage!=TripStage.Home&&w.VehicleBodiesOverlap(Ahead(c,.002,out var heading),heading,o.Position,o.Heading)).Select(o=>o.Id).ToArray()})},new JsonSerializerOptions{IncludeFields=true,Converters={new System.Text.Json.Serialization.JsonStringEnumConverter()}}));}}
